mapper.select:
SELECT *
FROM stores
WHERE store_type=#{type}


SELECT s.*, ROUND(AVG(r.rating),2) AS avgRating, COUNT(r.review_id) AS countRating
FROM stores s
INNER JOIN reviews r ON s.store_id = r.store_id
WHERE s.store_id = #{storeId}
GROUP BY s.store_id;


select image_id, file_name, file_type, display_no, created_at, updated_at
from image_file
where store_id = #{storeId} and reg_id = #{ownerId}


SELECT store_id, store_name, owner_id, store_type, road_address, description, file_name
FROM stores
WHERE owner_id = #{ownerId}
